import Link from "next/link";
import SERVICES from "~/page/Services/service";

// Show a representative slice of Pinktra's real service catalog rather than
// inventing generic categories — the full list lives on /services.
const FEATURED_SLUGS = [
  "business-website-development",
  "custom-web-application-development",
  "mobile-app-development",
  "ecommerce-development",
  "ai-integration",
];

const FEATURED_SERVICES = FEATURED_SLUGS.map((slug) =>
  SERVICES.find((s) => s.slug === slug),
).filter((s): s is (typeof SERVICES)[number] => Boolean(s));

const Services = () => {
  return (
    <section className="hp-section hp-services hp-highlights">
      <div className="hp-container hp-services-inner">
        <div className="hp-services-copy">
          <div className="hp-section-label">Digital Development Services</div>
          <h2 className="hp-section-title">Have an Idea? Let&apos;s Build It.</h2>
          <p className="hp-section-sub" style={{ marginBottom: 0 }}>
            Beyond learning and products, Pinktra provides professional development services —
            custom digital solutions built for customers.
          </p>
          <ul className="hp-services-list">
            {FEATURED_SERVICES.map((service) => (
              <li key={service.slug}>
                <span className="hp-services-check">✓</span>
                {service.title}
              </li>
            ))}
          </ul>
          <div className="hp-services-actions">
            <Link href="/services" className="hp-btn-primary">
              View Services
            </Link>
            <Link href="/work" className="hp-btn-secondary">
              See Our Work
            </Link>
          </div>
        </div>

        <div className="hp-services-card hp-glass">
          <span className="hp-product-icon-emoji">🚀</span>
          <h3>Products vs. Services</h3>
          <p>
            <strong>Products</strong> are Pinktra's own creations, ready to use today.
            <br /> <strong>Services</strong> are custom solutions Pinktra builds for you.
          </p>
        </div>
      </div>
    </section>
  );
};

export default Services;
