import Link from "next/link";
import PRODUCTS from "~/page/Products/product";

// Feature one product per category so the homepage teaser reflects the
// actual breadth of what Pinktra builds. Falls back gracefully if a
// category has no product yet.
const FEATURED_SLUGS = ["prompts", "habito", "smc-terminal"];

const FEATURED_PRODUCTS = FEATURED_SLUGS.map((slug) =>
  PRODUCTS.find((p) => p.slug === slug),
).filter((p): p is (typeof PRODUCTS)[number] => Boolean(p));

const Products = () => {
  return (
    <section className="hp-section hp-products hp-highlights">
      <div className="hp-container">
        <div className="hp-section-label">Pinktra Products</div>
        <h2 className="hp-section-title">Tools Built for Real Life</h2>
        <p className="hp-section-sub">
          Pinktra doesn&apos;t just teach — it builds. These are Pinktra&apos;s own digital
          products, designed to help you apply what you learn.
        </p>
        <div className="hp-products-grid">
          {FEATURED_PRODUCTS.map((product) => {
            const hostname = new URL(product.url).hostname.replace(/^www\./, "");

            return (
              <a
                key={product.slug}
                href={product.url}
                target="_blank"
                rel="noopener noreferrer"
                className="hp-product-card hp-glass"
              >
                <span className="hp-product-icon">
                  <img
                    src={`${product.url}/android-chrome-512x512.png`}
                    alt=""
                    aria-hidden="true"
                    loading="lazy"
                  />
                </span>
                <span className="hp-product-audience">{product.category}</span>
                <h3>{product.title}</h3>
                <p className="hp-product-desc">{product.description}</p>
                <span className="hp-product-link">Visit {hostname} ↗</span>
              </a>
            );
          })}
        </div>
        <div className="hp-products-more">
          <Link href="/products" className="hp-btn-secondary">
            View All Products
          </Link>
        </div>
      </div>
    </section>
  );
};

export default Products;
