import React from "react";

const AREAS = [
  { icon: "💻", title: "Technology", color: "#e8f4ff" },
  { icon: "🏃", title: "Health & Fitness", color: "#e8fff0" },
  { icon: "💰", title: "Finance", color: "#fff8e8" },
  { icon: "⚡", title: "Productivity", color: "#f0e8ff" },
  { icon: "🎓", title: "Education", color: "#ffe8f4" },
  { icon: "🧠", title: "Self Improvement", color: "#e8fff8" },
  { icon: "📈", title: "Trading", color: "#fff0e8" },
  { icon: "🌿", title: "Lifestyle", color: "#f4ffe8" },
  { icon: "📄", title: "Reference", color: "#e8f0ff" },
  { icon: "🎯", title: "Miscellaneous", color: "#ffe8e8" },
];

const KnowledgeAreas = () => {
  return (
    <section className="hp-section hp-areas hp-highlights">
      <div className="hp-container">
        <div className="hp-section-label">Explore Learning</div>
        <h2 className="hp-section-title">Learn Across Every Domain</h2>
        <p className="hp-section-sub">
          Ten broad domains of knowledge, each covering practical guides, tutorials, and references
          — continuously organized and expanding.
        </p>
        <div className="hp-areas-grid">
          {AREAS.map((area, index) => (
            <div
              key={index}
              className="hp-area-card hp-glass"
              style={{ "--area-bg": area.color } as React.CSSProperties}
            >
              <span className="hp-area-icon">{area.icon}</span>
              <span className="hp-area-title">{area.title}</span>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default KnowledgeAreas;
