const STEPS = [
  {
    step: "01",
    label: "Learn",
    desc: "Study clear, practical guides across technology, finance, health, business, and more.",
  },
  {
    step: "02",
    label: "Apply",
    desc: "Put what you've learned into practice using Pinktra's own tools and products.",
  },
  {
    step: "03",
    label: "Build",
    desc: "Need something custom? Pinktra's team can design and build it for you.",
  },
];

const LearningConnection = () => {
  return (
    <section className="hp-section hp-connect">
      <div className="hp-container">
        <div className="hp-section-label">One Connected Platform</div>
        <h2 className="hp-section-title">Learn Something. Put It to Work.</h2>
        <p className="hp-section-sub">
          Pinktra isn&apos;t three separate websites — it&apos;s one ecosystem. Learn a concept,
          apply it with a Pinktra product, and build something bigger when you're ready.
        </p>
        <div className="hp-workflow-row hp-connect-row">
          {STEPS.map((item, index) => (
            <div key={item.step} className="hp-workflow-item">
              <div className="hp-workflow-card hp-glass">
                <span className="hp-workflow-step">{item.step}</span>
                <h3>{item.label}</h3>
                <p>{item.desc}</p>
              </div>
              {index < STEPS.length - 1 && <div className="hp-workflow-arrow">→</div>}
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default LearningConnection;
