import Link from "next/link";
import HeroBackground from "./HeroBackground";

const Hero = () => {
  return (
    <section className="hp-hero">
      <HeroBackground />
      <div className="hp-hero-inner">
        <span className="hp-hero-badge">Learning &amp; Digital Products</span>
        <h1 className="hp-hero-title">
          Learn. Discover. <span className="hp-hero-brand">Build.</span>
        </h1>
        <p className="hp-hero-tagline">Knowledge for every curiosity.</p>
        <p className="hp-hero-desc">
          Pinktra is a platform for learning across technology, science, finance, health, business,
          and more — paired with practical digital products you can put to work right away. When you
          need something custom, our team can build it for you.
        </p>
        <div className="hp-hero-actions">
          <Link href="/learn" className="hp-btn-primary">
            Start Learning
          </Link>
          <Link href="/products" className="hp-btn-secondary">
            View Products
          </Link>
        </div>
        <Link href="/services" className="hp-hero-services-link">
          Need a website or app built? View Services →
        </Link>
      </div>
    </section>
  );
};

export default Hero;